properties.query:
let phish_events = EmailEvents | where ThreatTypes has "Phish" | summarize phish_time=min(TimeGenerated) by RecipientEmailAddress;
let cred_events = SigninLogs | where ResultType == 0 and TimeGenerated > ago(24h) and ClientAppUsed has_any ("Exchange ActiveSync", "IMAP") | summarize cred_time=min(TimeGenerated) by UserPrincipalName;
phish_events | join kind=inner cred_events on $left.RecipientEmailAddress == $right.UserPrincipalName | where cred_time - phish_time between (0min .. 1440min)
